=== file: main.loom ===
budget { tokens: 12000  calls: 8 }

tool Mail {
    use: email
    host: env.MAIL_HOST
    username: env.MAIL_USERNAME
    password: env.MAIL_PASSWORD
    from: env.MAIL_FROM
    allow_to: env.MAIL_ALLOWED_RECIPIENT
    tls: true
}

intentclassifier ApplicationQualification {
    model: "gpt-6-luna"
    choose kind: strong | maybe | reject
    confidence at least 0.8 else escalate
}

intentclassifier RecruiterSendApproval {
    model: "gpt-6-luna"
    choose kind: send | decline
    confidence at least 0.8 else escalate
}

agent InvitationDrafter {
    model: "gpt-6-luna"
    prompt: "invitation-drafter"
    temperature: 0.2
    guard { pii: mask }
    output_schema: {
        subject: string,
        body: string
    }
}

agent InvitationSender {
    model: "gpt-6-luna"
    prompt: "invitation-sender"
    tools: [Mail]
    approve: [Mail]
    guard { pii: mask }
    output_schema: {
        status: enum["SENT", "FAILED"],
        detail: string
    }
}

workflow Main(role_specification_q7, job_qualification_summary_q7, recipient_address_q7) {
    intentclassify ApplicationQualification on "Give an advisory label based only on job-related qualifications and their relevance to the stated role. Exclude sensitive personal data and protected characteristics. The label must never change applicant status or be treated as a hiring decision. Choose strong, maybe, or reject. If evidence is insufficient or ambiguous, do not guess.\n\nRole requirements:\n{role_specification_q7}\n\nJob-related qualifications:\n{job_qualification_summary_q7}" -> qualification_route_q7 retry 1 backoff 2s timeout 30s on_failure {
        return { advisory: "unavailable", outcome: "review", reason: "Classification failed or could not be completed within budget. No invitation was drafted or sent, and applicant status was not changed." }
    }

    alt (qualification_route_q7.kind == "unsure") {
        return { advisory: "unsure", outcome: "review", reason: "Qualification evidence was insufficient or ambiguous. Recruiter review is needed; no invitation was drafted or sent, and applicant status was not changed." }
    } else {
        alt (qualification_route_q7.kind == "strong") {
            delegate "Draft a concise, professional invitation for recruiter review. Use only this role and job-related information. Do not assess or change applicant status, infer sensitive characteristics, or add unsupported claims.\n\nRole requirements:\n{role_specification_q7}\n\nJob-related qualifications:\n{job_qualification_summary_q7}" to InvitationDrafter -> invitation_draft_q7 expecting {
                subject: string,
                body: string
            } retry 1 backoff 2s timeout 45s on_failure {
                return { advisory: "strong", outcome: "draft_failed", reason: "Invitation drafting failed or could not be completed within budget. No invitation was sent, and applicant status was not changed." }
            }

            human_prompt "Review this exact invitation and recipient. Type SEND to approve sending this exact draft to this exact recipient, or DECLINE. Any other response will not authorize sending.\n\nRecipient: {recipient_address_q7}\nSubject: {invitation_draft_q7.subject}\n\nDraft:\n{invitation_draft_q7.body}" -> recruiter_reply_q7

            intentclassify RecruiterSendApproval on "Classify the recruiter's response about sending the displayed invitation to the displayed recipient. Approve only an exact, explicit SEND response. DECLINE means decline. Every other response is unsure; do not infer approval.\n\nRecruiter's response:\n{recruiter_reply_q7}" -> send_approval_q7 retry 1 backoff 2s timeout 30s on_failure {
                return { advisory: "strong", outcome: "approval_review", reason: "Recruiter approval could not be reliably classified. No invitation was sent, and applicant status was not changed." }
            }

            alt (send_approval_q7.kind == "send") {
                delegate "Send only the recruiter-approved invitation to the exact approved recipient below. Do not alter the subject, body, or recipient, and do not send any other message. Use Mail once. Report SENT only if Mail confirms success; if the call fails or its outcome is uncertain, report FAILED and do not retry.\n\nApproved recipient: {recipient_address_q7}\nApproved subject: {invitation_draft_q7.subject}\nApproved body:\n{invitation_draft_q7.body}" to InvitationSender -> mail_outcome_q7 expecting {
                    status: enum["SENT", "FAILED"],
                    detail: string
                } retry 0 backoff 2s timeout 45s on_failure {
                    return { advisory: "strong", outcome: "send_failed", reason: "Mail failed or its outcome was uncertain. Recruiter follow-up is required; applicant status was not changed." }
                }

                alt (mail_outcome_q7.status == "SENT") {
                    return { advisory: "strong", outcome: "sent", reason: "The recruiter-approved invitation was sent. The advisory label did not change applicant status." }
                } else {
                    return { advisory: "strong", outcome: "send_failed", reason: "Mail did not confirm success. Recruiter follow-up is required; applicant status was not changed." }
                }
            } else {
                alt (send_approval_q7.kind == "decline") {
                    return { advisory: "strong", outcome: "declined", reason: "The recruiter declined. No invitation was sent, and applicant status was not changed." }
                } else {
                    return { advisory: "strong", outcome: "approval_review", reason: "The response was not an unambiguous approval. Recruiter review is needed; no invitation was sent, and applicant status was not changed." }
                }
            }
        } else {
            alt (qualification_route_q7.kind == "maybe") {
                return { advisory: "maybe", outcome: "review", reason: "This advisory label does not trigger an invitation. Recruiter review is needed; applicant status was not changed." }
            } else {
                return { advisory: "reject", outcome: "review", reason: "This advisory label does not reject or otherwise change applicant status. Recruiter review is needed; no invitation was drafted or sent." }
            }
        }
    }
}
